use hec_native_ic::{counted,instance::{pick_instance,prime_factors},poly::Poly,fp::Fp,rng::Rng};
fn full(v:u16,g:usize)->u16{v|(((v.count_ones()%2)as u16)<<(2*g+1))}
fn project(mut v:u16,g:usize)->u16{assert_eq!(v.count_ones()%2,0);if(v>>(2*g))&1!=0{v^=(1u16<<(2*g+2))-1;}v&((1u16<<(2*g))-1)}
fn action(v:u16,p:&[usize],g:usize)->u16{let mask=full(v,g);let mut out=0;for(i,&j)in p.iter().enumerate(){if(mask>>i)&1!=0{out|=1<<j;}}project(out,g)}
fn permutation(ds:&[usize],g:usize)->Vec<usize>{let mut p=(0..2*g+2).collect::<Vec<_>>();let mut start=0;for &d in ds{for i in 0..d{p[start+i]=start+(i+1)%d;}start+=d;}assert_eq!(start,2*g+1);p}
fn rank(mut a:Vec<Vec<u64>>,f:&Fp)->usize{let n=a.first().map_or(0,|r|r.len());let mut r=0;for j in 0..n{let Some(i)=(r..a.len()).find(|&i|a[i][j]!=0)else{continue;};a.swap(r,i);let z=f.inv(a[r][j]);for k in j..n{a[r][k]=f.mul(a[r][k],z);}for i in 0..a.len(){if i==r{continue;}let z=a[i][j];for k in j..n{a[i][k]=f.sub(a[i][k],f.mul(z,a[r][k]));}}r+=1;}r}
fn main(){counted::disable();let f=Fp::new(17);let mut determinant_checks=0;let mut distinct_source_shifts=0;for a in 0..17{for b in 0..17{for c in 0..17{for d in 0..17{let plus=[f.add(a,c),f.add(b,d)];let minus=[f.sub(a,c),f.sub(b,d)];let det=f.sub(f.mul(plus[0],minus[1]),f.mul(minus[0],plus[1]));assert_eq!(det,f.mul(2,f.sub(f.mul(b,c),f.mul(a,d))));assert_eq!(rank(vec![plus.to_vec(),minus.to_vec()],&f)==2,det!=0);determinant_checks+=1;}}if b!=0{let det=f.sub(f.mul(f.add(a,1),b),f.mul(f.sub(a,1),b));assert_eq!(det,f.mul(2,b));assert_ne!(det,0);distinct_source_shifts+=1;}}}
let mut rng=Rng::new(2026112600);for _ in 0..512{let a=(0..5).map(|_|rng.below(17)).collect::<Vec<_>>();let b=(0..5).map(|_|rng.below(17)).collect::<Vec<_>>();let sum=a.iter().zip(&b).map(|(&x,&y)|f.add(x,y)).collect::<Vec<_>>();let diff=a.iter().zip(&b).map(|(&x,&y)|f.sub(x,y)).collect::<Vec<_>>();assert_eq!(rank(vec![a.clone(),b.clone()],&f),rank(vec![sum.clone(),diff.clone()],&f));for i in 0..5{assert_eq!(f.mul(f.add(sum[i],diff[i]),f.inv(2)),a[i]);assert_eq!(f.mul(f.sub(sum[i],diff[i]),f.inv(2)),b[i]);}}
let valid=vec![1,16,1];let global=valid.iter().map(|&x|f.neg(x)).collect::<Vec<_>>();assert_eq!(rank(vec![valid.clone(),global],&f),1);let false_branch=vec![16,16,1];assert_eq!(rank(vec![valid,false_branch],&f),2);assert_eq!(f.sub(f.sub(6,1),5),0);assert_ne!(f.sub(f.sub(f.neg(6),1),5),0);println!("ALGEBRA determinant_checks={determinant_checks} known_source_shift_nonzero_checks={distinct_source_shifts} invertible_sum_difference_checks=512 global_negation_rank=1 wrong_branch_rejected=true");
let identity=permutation(&[1,1,1,1,1],2);assert_eq!((0..16).filter(|&v|action(v,&identity,2)==v).count(),16);let cyclic=permutation(&[5],2);assert_eq!((0..16).filter(|&v|action(v,&cyclic,2)==v).count(),1);
let old=include_str!("../native-two-kernel/CONTROL.txt");let mut models=0;let mut g2=0;for l in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){let v=l.split('\t').collect::<Vec<_>>();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c.to_string(),v[2]);assert_eq!(inst.ell,ell);let c=inst.curve;assert_eq!(c.f.c[..c.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);assert_eq!(prime_factors(ell),vec![ell]);assert!(!c.is_zero(&inst.d1));assert!(c.is_zero(&c.mul(&inst.d1,ell)));let n=2*g+1;let mut xp=Poly::x();let mut counts=vec![0usize;n+1];for i in 1..=n{xp=xp.powmod(p,&c.f,&c.fp);let degree=Poly::gcd(&c.f,&xp.sub(&Poly::x(),&c.fp),&c.fp).deg()as usize;let used=(1..i).filter(|j|i%j==0).map(|j|j*counts[j]).sum::<usize>();assert!(degree>=used);assert_eq!((degree-used)%i,0);counts[i]=(degree-used)/i;}let mut degrees=Vec::new();for i in 1..=n{degrees.extend(std::iter::repeat_n(i,counts[i]));}assert_eq!(degrees.iter().sum::<usize>(),n);let line=old.lines().find(|l|l.starts_with(&format!("CASE genus={g} p={p} "))).unwrap();let previous=line.split("factor_degrees=[").nth(1).unwrap().split(']').next().unwrap().split(',').map(|s|s.trim().parse().unwrap()).collect::<Vec<usize>>();assert_eq!(degrees,previous);let perm=permutation(&degrees,g);let mut fixed=0usize;for a in 0..1u16<<(2*g){assert_eq!(project(full(a,g),g),a);if action(a,&perm,g)==a{fixed+=1;}}assert_eq!(fixed,1usize<<(degrees.len()-1));let dimension=fixed.ilog2();let mut ceiling=0u64;while ceiling*ceiling<p{ceiling+=1;}let upper=(ceiling+1).pow((2*g)as u32);let full_torsion=1u64<<(2*g);assert!((full_torsion as u128)*(ell as u128)>upper as u128);if g==2{assert!(fixed<16);g2+=1;}println!("MODEL g={g} p={p} c={} ell={ell} factor_degrees={degrees:?} rational_two_torsion_dimension={dimension} rational_two_torsion_points={fixed} full_two_torsion_points={full_torsion} integer_hasse_upper={upper} full_torsion_times_ell={} base_field_full_two_torsion_isogeny_excluded=true",inst.c,full_torsion*ell);models+=1;}
assert_eq!(models,11);assert_eq!(g2,6);eprintln!("PASS original_models=11 original_genus2_fast_split_model_admission_excluded=6 pair_rank_identities=true no_kummer_circuit_or_speed_claim=true");}
